#include <stdint.h>
#include "blaze_rt.h"

float dotProduct(const float* a, const float* b, int64_t n) {
  float* copy = (float*)blaze_rt_allocate((size_t)n * sizeof(float));
  for (int64_t i = 0; i < n; i += 1) copy[i] = a[i];
  float total = 0.0f;
  for (int64_t i = 0; i < n; i += 1) total += copy[i] * b[i];
  blaze_rt_release(copy);
  return total;
}
